const content = $json.choices?.[0]?.message?.content;

if (!content) {
  throw new Error('Groq did not return a response. Check your API key and request.');
}

let result;
try {
  result = JSON.parse(content);
} catch (error) {
  const cleaned = content.replace(/^```json\s*/i, '').replace(/\s*```$/i, '').trim();
  result = JSON.parse(cleaned);
}

return [{
  json: {
    version: $('Git Commits Input').first().json.version,
    release_title: result.release_title,
    summary: result.summary,
    release_notes: result.release_notes,
    changelog: result.changelog,
    generated_by: 'n8n + Groq API'
  }
}];

const data = $input.first().json;

const added = data.changelog?.Added || [];
const changed = data.changelog?.Changed || [];
const fixed = data.changelog?.Fixed || [];
const documentation = data.changelog?.Documentation || [];
const other = data.changelog?.Other || [];

function createList(items) {
  if (!items.length) {
    return '<p class="empty">No changes in this category.</p>';
  }

  return '<ul>' + items.map(item => `<li>${item}</li>`).join('') + '</ul>';
}

const html = `
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">

<title>${data.release_title || 'Release Notes'}</title>

<style>

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: Arial, Helvetica, sans-serif;
  background: #f4f6f9;
  color: #222;
}

.container {
  max-width: 900px;
  margin: 40px auto;
  padding: 20px;
}

.header {
  background: linear-gradient(135deg, #4f46e5, #7c3aed);
  color: white;
  padding: 40px;
  border-radius: 20px;
  box-shadow: 0 10px 30px rgba(0,0,0,0.15);
}

.header h1 {
  margin: 0 0 10px;
  font-size: 34px;
}

.version {
  display: inline-block;
  background: rgba(255,255,255,0.2);
  padding: 7px 14px;
  border-radius: 20px;
  font-weight: bold;
}

.summary {
  margin-top: 20px;
  font-size: 17px;
  line-height: 1.6;
}

.card {
  background: white;
  margin-top: 22px;
  padding: 25px;
  border-radius: 16px;
  box-shadow: 0 5px 20px rgba(0,0,0,0.08);
}

.card h2 {
  margin-top: 0;
  font-size: 22px;
}

.card ul {
  padding-left: 22px;
}

.card li {
  margin: 10px 0;
  line-height: 1.5;
}

.added {
  border-left: 6px solid #22c55e;
}

.changed {
  border-left: 6px solid #3b82f6;
}

.fixed {
  border-left: 6px solid #ef4444;
}

.docs {
  border-left: 6px solid #f59e0b;
}

.other {
  border-left: 6px solid #8b5cf6;
}

.empty {
  color: #888;
  font-style: italic;
}

.footer {
  text-align: center;
  margin-top: 30px;
  color: #777;
  font-size: 14px;
}

</style>
</head>

<body>

<div class="container">

  <div class="header">

    <h1>🚀 ${data.release_title || 'Release Notes'}</h1>

    <span class="version">
      ${data.version || 'Version'}
    </span>

    <p class="summary">
      ${data.summary || 'No summary available.'}
    </p>

  </div>


  <div class="card added">

    <h2>✨ Added</h2>

    ${createList(added)}

  </div>


  <div class="card changed">

    <h2>🔄 Changed</h2>

    ${createList(changed)}

  </div>


  <div class="card fixed">

    <h2>🐛 Fixed</h2>

    ${createList(fixed)}

  </div>


  <div class="card docs">

    <h2>📚 Documentation</h2>

    ${createList(documentation)}

  </div>


  <div class="card other">

    <h2>📌 Other</h2>

    ${createList(other)}

  </div>


  <div class="footer">

    Generated automatically using n8n + Groq AI

  </div>

</div>

</body>
</html>
`;

return [
  {
    json: {
      ...data,
      html: html
    }
  }
];
